import { render } from "@solidjs/web";
import { createRouter, useLocation, useNavigate } from "@solidjs/router";
import { LocusBreadcrumb } from "./locus-breadcrumb";
import { locusAddressMembers } from "./locus-address";
import { parentScope, type LocusScope } from "./locus-scope";
import type { LocusRootData } from "./locus-root-data";
import { installWorkspaceAddress } from "./workspace-address";
import { scopeFromWorkspace, scopeToWorkspace, workspaceSourceFromKey, workspaceSourceKey,
  type WorkspaceLens } from "./workspace-wire";
import type { LocusAddressInput } from "./locus-address-inputs";

