declare const exactAddressCallTable: Record<string, unknown>;

function sourceCallKey(name: string, args: unknown[]): string {
  // Focus is host transport beside the Fenel member descriptor, not policy.
  const members = (args[0] as Array<{ id: string; name: string; aliases: string[]; position: number }>).map(member => ({
    id: member.id, name: member.name, aliases: member.aliases, position: member.position,
  }));
  return JSON.stringify([name, members, ...args.slice(1)]);
}

function fixtureWorkspaceCall<T>(name: string, ...args: unknown[]): T {
  const key = sourceCallKey(name, args);
  if (!Object.hasOwn(exactAddressCallTable, key)) throw new Error(`No current-source fixture verdict for ${key}`);
  return structuredClone(exactAddressCallTable[key]) as T;
}

type FixtureControls = {
  enter: (segment: string) => void;
  navigate: (url: string) => void;
  selectSource: (key: string) => void;
  up: () => void;
  refuseNextFocus: () => void;
  holdNextRoot: () => void;
  releaseRoots: () => void;
  releasePreparations: () => void;
  inputsChanged: (inputs: readonly LocusAddressInput[]) => void;
  inputsHandled: (id?: number) => void;
  state: () => unknown;
};
let controls: FixtureControls | undefined;
let dispose: (() => void) | undefined;
let nextMountHoldsPreparation = false;
let nextMountRememberedLens: { source: string; focus: LocusScope } | undefined;
let instancesCreated = 0;

function AddressFixture() {
  const instance = ++instancesCreated;
  const location = useLocation();
  const navigate = useNavigate();
  const [lens, setLens] = createSignal<WorkspaceLens>({
    $tag: "WorkspaceLens", id: "fixture-lens", title: { $tag: "Nothing" },
    source: nextMountRememberedLens ? workspaceSourceFromKey(nextMountRememberedLens.source) : { $tag: "PublicSource" },
    focus: nextMountRememberedLens ? scopeToWorkspace(nextMountRememberedLens.focus) : { $tag: "RootFocus" },
    presentation: { $tag: "AutomaticPresentation" },
  });
  const [failed, setFailed] = createSignal<string>();
  const rootReads: string[] = [];
  let prepared = 0;
  let focused = 0;
  let refuseFocus = false;
  let holdRoot = false;
  const pendingRoots: Array<() => void> = [];
  let holdPreparation = nextMountHoldsPreparation;
  const pendingPreparations: Array<() => void> = [];
  const activeScope = () => scopeFromWorkspace(lens().focus);
  const rootFor = () => ADDRESS_FIXTURE_ROOTS[workspaceSourceKey(lens().source)]!;
  const address = installWorkspaceAddress({
    enabled: true, active: lens,
    accounts: () => [{ id: "account-allowed", label: "Rom", slug: "rom" }],
    prepare: async () => {
      prepared++;
      if (holdPreparation) {
        holdPreparation = false;
        await new Promise<void>(resolve => pendingPreparations.push(resolve));
      }
    },
    operate: async (operation, options) => {
      options?.assertCurrent?.();
      return fixtureWorkspaceCall(operation.kind, ...operation.args);
    },
    root: async source => {
      const key = workspaceSourceKey(source);
      rootReads.push(key);
      const root = ADDRESS_FIXTURE_ROOTS[key];
      if (!root) throw new Error("Fixture reader refused an unavailable source.");
      if (holdRoot) {
        holdRoot = false;
        await new Promise<void>(resolve => pendingRoots.push(resolve));
      }
      return root;
    },
    focus: async (source, focus, assertCurrent) => {
      assertCurrent?.();
      focused++;
      if (refuseFocus) { refuseFocus = false; return false; }
      setLens(previous => ({ ...previous, source, focus: scopeToWorkspace(focus) }));
      return true;
    },
    failed: setFailed,
  });
  function explicitFocus(focus: LocusScope) {
    address.navigationStarted();
    setLens(previous => ({ ...previous, focus: scopeToWorkspace(focus) }));
    address.navigated();
  }
  controls = {
    enter(segment) {
      const { members, positional } = locusAddressMembers(rootFor(), activeScope());
      const selected = fixtureWorkspaceCall<{ $tag: "Ok" | "Err"; _0: number | string }>("addressMemberIndex", members, segment, positional);
      if (selected.$tag !== "Ok") throw new Error(String(selected._0));
      const member = members[selected._0 as number];
      if (!member) throw new Error("Fixture child is unavailable.");
      explicitFocus(member.focus);
    },
    navigate: url => { navigate(url); },
    selectSource(key) {
      address.navigationStarted();
      setLens(previous => ({ ...previous, source: workspaceSourceFromKey(key), focus: { $tag: "RootFocus" } }));
      address.navigated();
    },
    up() {
      const parent = parentScope(activeScope());
      if (parent) explicitFocus(parent);
    },
    refuseNextFocus() { refuseFocus = true; },
    holdNextRoot() { holdRoot = true; },
    releaseRoots() { for (const release of pendingRoots.splice(0)) release(); },
    releasePreparations() { for (const release of pendingPreparations.splice(0)) release(); },
    inputsChanged: inputs => { address.inputsChanged(inputs); },
    inputsHandled(id) {
      const currentId = id ?? address.inputs()?.id;
      if (currentId !== undefined) address.inputsHandled(currentId);
    },
    state: () => untrack(() => ({ source: workspaceSourceKey(lens().source), focus: activeScope(),
      address: location.pathname + location.search, loading: address.initialLoading(),
      failed: failed(), rootReads: [...rootReads], prepared, focused, instance,
      inputRequest: address.inputs(),
      pendingRoots: pendingRoots.length, pendingPreparations: pendingPreparations.length, up: parentScope(activeScope()) })),
  };
  return <main>
    <LocusBreadcrumb scope={activeScope()} rootLabel={workspaceSourceKey(lens().source)}
      itemName={(_viewId, itemId) => rootFor().items.find(item => item.id === itemId)?.representations?.Codeable?.codeName as string | undefined}
      onNavigate={explicitFocus} />
    <output data-address-fixture-state>{JSON.stringify(controls!.state())}</output>
  </main>;
}

// Root and deeper data paths share this actual outlet route key, matching the
// production catch-all. A route replacement would dispose AddressFixture.
const Router = createRouter({ routes: [{ path: "*data", component: AddressFixture }] });

Object.assign(globalThis, { workspaceAddressFixture: {
  mount(options: { holdPreparation?: boolean; rememberedLens?: { source: string; focus: LocusScope } } = {}) {
    dispose?.();
    controls = undefined;
    nextMountHoldsPreparation = options.holdPreparation === true;
    nextMountRememberedLens = options.rememberedLens;
    dispose = render(() => <Router>{props => props.children}</Router>, document.getElementById("fixture")!);
  },
  state: () => controls?.state(),
  enter: (segment: string) => controls!.enter(segment),
  navigate: (url: string) => controls!.navigate(url),
  selectSource: (key: string) => controls!.selectSource(key),
  up: () => controls!.up(),
  refuseNextFocus: () => controls!.refuseNextFocus(),
  holdNextRoot: () => controls!.holdNextRoot(),
  releaseRoots: () => controls!.releaseRoots(),
  releasePreparations: () => controls!.releasePreparations(),
  inputsChanged: (inputs: readonly LocusAddressInput[]) => controls!.inputsChanged(inputs),
  inputsHandled: (id?: number) => controls!.inputsHandled(id),
  close() { dispose?.(); dispose = undefined; controls = undefined; },
} });
